-- mira - 36 Product catalog from Excel
-- Ejecutar despues de 35_internal_staff.sql.
-- Carga el catalogo base desde LISTA DE PRODUCTOS.xlsx usando nombre comercial e ingrediente activo.

alter table public.task_materials
add column if not exists composition text;

create index if not exists products_company_name_lookup_idx
on public.products(company_id, lower(trim(name)));

create index if not exists task_materials_product_id_idx
on public.task_materials(product_id)
where product_id is not null;

