source_products as (
  select distinct on (lower(trim(name)))
    trim(name) as name,
    nullif(trim(composition), '') as composition
  from raw_products
  where nullif(trim(name), '') is not null
  order by lower(trim(name)), (nullif(trim(composition), '') is not null) desc
)
update public.products product
set composition = source.composition,
    updated_at = now()
from source_products source
where product.company_id is not null
  and lower(trim(product.name)) = lower(trim(source.name))
  and source.composition is not null
  and nullif(trim(coalesce(product.composition, '')), '') is null;

