source_products as (
  select distinct on (lower(trim(name)))
    trim(name) as name,
    nullif(trim(composition), '') as composition
  from raw_products
  where nullif(trim(name), '') is not null
  order by lower(trim(name)), (nullif(trim(composition), '') is not null) desc
)
insert into public.products (company_id, name, composition)
select company.id, source.name, source.composition
from public.companies company
cross join source_products source
where not exists (
  select 1
  from public.products product
  where product.company_id = company.id
    and lower(trim(product.name)) = lower(trim(source.name))
);
